test "test_trade_report_codec" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();

    const msg = TradeReport{
        .req_id = 123456789,
        .channel_id = 1234,
        .adapter = 42,
        .account = "aaaaaaaaaaaaaaaa",
        .cl_ord_id = "aaaaaaaaaaaaaaaa",
        .order_id = "aaaaaaaaaaaaaaaa",
        .exec_id = "aaaaaaaaaaaaaaaa",
        .exec_type = 42,
        .ord_status = 42,
        .security_id = "aaaaaaaaaaaa",
        .side = 42,
        .last_px = -123456789,
        .last_qty = -123456789,
        .cum_qty = -123456789,
        .leaves_qty = -123456789,
        .ts_ns = 123456789,
        .raw_ref = 123456789,
    };

    var buf = codec.Buffer.init(allocator, .big);
    defer buf.deinit();
    try msg.encode(&buf);

    var reader = codec.Reader.init(buf.written(), .big);
    const decoded = try TradeReport.decode(allocator, &reader);
    defer decoded.deinit(allocator);
    try std.testing.expect(msg.eql(decoded));
}
